    for c in text.chars() {
        if c.is_alphabetic() {
            letters += 1;
        } else if c.is_digit(10) {
            digits += 1;
            current_streak += 1;
            longest_streak = longest_streak.max(current_streak);
        } else if c == ' ' {
            spaces += 1;
            current_streak = 0;
        } else {
            others += 1;
            current_streak = 0;
        }
    }
    println!("{}", letters);
    println!("{}", digits);
    println!("{}", spaces);
    println!("{}", others);
    println!("{}", longest_streak);
    let mut digit_string = String::new();
    for c in text.chars() {
        if c.is_digit(10) {
            digit_string.push(c);
        }
    }
    println!("{}", digit_string);
}

